const nextReadyAt = `-- name: NextReadyAt :one
SELECT coins.ready_at
FROM coins
JOIN claims ON claims.delegation_id = coins.delegation_id AND claims.input = coins.input
JOIN delegations ON delegations.id = coins.delegation_id
WHERE coins.status = 'present' AND NOT coins.held AND coins.ready_at > $1::timestamptz AND delegations.status = 'active'
  AND CASE WHEN claims.locktime >= 500000000 THEN claims.locktime <= $2::bigint ELSE claims.locktime <= $3::bigint END
  AND NOT EXISTS (SELECT 1 FROM coins h WHERE h.delegation_id = coins.delegation_id AND h.status = 'present' AND h.held)
ORDER BY coins.ready_at
LIMIT 1
`

type NextReadyAtParams struct {
	Now        time.Time
	MedianTime int64
	Height     int64
}

// the earliest time after now a coin ListReadyCoins would consider becomes ready; no row when none will
func (q *Queries) NextReadyAt(ctx context.Context, arg NextReadyAtParams) (sql.NullTime, error) {
	row := q.db.QueryRowContext(ctx, nextReadyAt, arg.Now, arg.MedianTime, arg.Height)
	var ready_at sql.NullTime
	err := row.Scan(&ready_at)
	return ready_at, err
}

const pruneDelegations = `-- name: PruneDelegations :execrows
DELETE FROM delegations
WHERE stream_id IS NOT NULL AND status = 'expired' AND expires_at <= $1::timestamptz
`

func (q *Queries) PruneDelegations(ctx context.Context, before time.Time) (int64, error) {
	result, err := q.db.ExecContext(ctx, pruneDelegations, before)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

